import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    weights = list(map(int, data[1:1+n]))
    operation = int(data[1+n])

    if n == 0:
        print("Selected Container Weight: 0")
        print("Size of Container: 4")
        return

    min_weight = min(weights)

    if operation == 0:
        new_weight = min_weight + 1
    else:
        new_weight = min_weight - 1
        if new_weight < 0:
            new_weight = 0

    print(f"Selected Container Weight: {new_weight}")
    print("Size of Container: 4")

if __name__ == "__main__":
    main()
